import{a2 as i,P as l,Q as d,S as a,V as e,$ as s,_ as r,C as t}from"./framework-04579a5f.js";const o={},c={href:"https://github.com/FlutterPlayer/ijkplayer",target:"_blank",rel:"noopener noreferrer"},u=a("code",null,"FPlayer",-1),p=r(`<h2 id="requirements" tabindex="-1"><a class="header-anchor" href="#requirements" aria-hidden="true">#</a> Requirements</h2><ul><li>Flutter <code>3.41.9</code> or a compatible release</li><li>Android: JDK 17 plus the Android SDK / NDK (consuming the prebuilt kernel doesn&#39;t need a local NDK build)</li><li>iOS / macOS: Xcode; on an Apple Silicon Mac you can use the arm64 simulator</li><li>Windows: a Windows host with the Visual Studio C++ toolchain</li><li>OpenHarmony: DevEco Studio, the OpenHarmony SDK, and a Flutter build with OHOS support (see <a href="/en/core/harmonyos-init">OpenHarmony setup</a>)</li></ul><h2 id="adding-the-dependency" tabindex="-1"><a class="header-anchor" href="#adding-the-dependency" aria-hidden="true">#</a> Adding the dependency</h2><p>Add the package to <code>pubspec.yaml</code>:</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">dependencies</span><span class="token punctuation">:</span>
  <span class="token key atrule">fplayer</span><span class="token punctuation">:</span> ^1.3.0
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>If you also want the bundled player panel, gestures, and the volume/brightness overlay, add the optional <code>fplayer_ui</code> package:</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">dependencies</span><span class="token punctuation">:</span>
  <span class="token key atrule">fplayer_ui</span><span class="token punctuation">:</span>
    <span class="token key atrule">git</span><span class="token punctuation">:</span>
      <span class="token key atrule">url</span><span class="token punctuation">:</span> https<span class="token punctuation">:</span>//github.com/FlutterPlayer/fplayer.git
      <span class="token key atrule">path</span><span class="token punctuation">:</span> packages/fplayer_ui
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Then fetch the packages:</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>flutter pub get
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><code>fplayer_ui</code> ships from the fplayer repository and isn&#39;t published separately on pub.dev. The core <code>fplayer</code> package works fine on its own.</p><h2 id="platform-setup" tabindex="-1"><a class="header-anchor" href="#platform-setup" aria-hidden="true">#</a> Platform setup</h2><h3 id="android" tabindex="-1"><a class="header-anchor" href="#android" aria-hidden="true">#</a> Android</h3><p>Android consumes the <code>fplayercore</code> AAR from Maven Central or from <code>android/local-repo</code>. Before the first build, run:</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>./tool/fetch_ijkplayer_packages.sh
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>If Gradle can&#39;t resolve <code>io.github.flutterplayer:fplayercore</code>, check that the fetch script above has run and look inside <code>android/local-repo</code>.</p><h3 id="ios-macos" tabindex="-1"><a class="header-anchor" href="#ios-macos" aria-hidden="true">#</a> iOS / macOS</h3><p>fplayer uses Swift Package Manager to download the <code>fplayercore</code> xcframework from the official ijkplayer releases. Enable SPM before the first build:</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>flutter config --enable-swift-package-manager
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>New projects need no Podfile and no <code>pod install</code>. Projects that still use CocoaPods can keep the podspec and pull the local framework in <code>Frameworks/</code> with the fetch script.</p><p>The iOS simulator uses the arm64 slice, so build on an Apple Silicon Mac.</p><h3 id="windows" tabindex="-1"><a class="header-anchor" href="#windows" aria-hidden="true">#</a> Windows</h3><p>The Windows example has to be built on a Windows host with the Visual Studio desktop C++ tools installed. fplayer links <code>fplayercore.dll</code> through CMake.</p><h3 id="openharmony" tabindex="-1"><a class="header-anchor" href="#openharmony" aria-hidden="true">#</a> OpenHarmony</h3><p>OpenHarmony needs its own Flutter OHOS distribution plus the DevEco toolchain. The full procedure lives in <a href="/en/core/harmonyos-init">OpenHarmony setup</a>.</p><h2 id="building" tabindex="-1"><a class="header-anchor" href="#building" aria-hidden="true">#</a> Building</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># Android</span>
flutter build apk

<span class="token comment"># iOS simulator (Apple Silicon)</span>
flutter build ios <span class="token parameter variable">--simulator</span> --no-codesign

<span class="token comment"># macOS</span>
flutter build macos

<span class="token comment"># Windows (must run on a Windows host)</span>
flutter build windows
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Before you build, run:</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>flutter clean
flutter pub get
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="next-steps" tabindex="-1"><a class="header-anchor" href="#next-steps" aria-hidden="true">#</a> Next steps</h2><ul><li><a href="/en/guide/quick">Quick start</a>: create a player and mount <code>FView</code></li><li><a href="/en/basic/api">Player API</a>: playback control, audio tracks, and status</li><li><a href="/en/skin/immanent">Built-in UI</a>: the full <code>fplayer_ui</code> panel</li></ul>`,30),h={href:"https://github.com/FlutterPlayer/fplayer/issues",target:"_blank",rel:"noopener noreferrer"};function m(b,v){const n=t("ExternalLinkIcon");return l(),d("div",null,[a("p",null,[e("fplayer is a Flutter media player plugin for Android, iOS, macOS, Windows, and OpenHarmony. Playback runs on the "),a("a",c,[e("FlutterPlayer/ijkplayer"),s(n)]),e(" kernel, and the Dart side talks to it through one API: "),u,e(".")]),p,a("p",null,[e("Hit a problem? Open an issue on "),a("a",h,[e("fplayer issues"),s(n)]),e(".")])])}const y=i(o,[["render",m],["__file","index.html.vue"]]);export{y as default};
